const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles=['星语法师','齿轮工匠','星际守护','森林游侠'];
const tones=['#ba9adc','#d7aa77','#8ac6cd','#aec487'];
const status=p=>p.status==='allowed'?'已允许':p.status==='blocked'?'已停用':'待允许';
const number=n=>Number(n??0).toLocaleString();
const date=n=>new Date(n).toLocaleString();
function device(a=''){return /iPad|Macintosh.*Mobile/i.test(a)?'iPad':/iPhone/i.test(a)?'iPhone':/Android/i.test(a)?'Android':/Windows/i.test(a)?'Windows':/Macintosh|Mac OS/i.test(a)?'Mac':'浏览器设备'}
export function profileView(data){const p=data.player,first=!p.name;if(first||p.status!=='allowed')return entryView(data);return `
 <p class="club-intro">${first?'选一个喜欢的形象，取个名字，即可申请入座。':'管理你的形象与筹码。'}</p>
 ${first?'<div class="club-welcome-credit"><span>首次入座</span><strong>2,000 <small>筹码</small></strong></div>':`<div class="club-account-summary"><div><span class="club-kicker">可用筹码</span><strong>${number(p.bank)}</strong></div><span class="club-status ${p.status}">${status(p)}</span>${p.activeRoom?`<span class="club-muted">${p.settling?'托管结算中':'牌桌中'} · ${number(p.tableBank)} 筹码</span>`:''}</div>`}
 <form data-profile><label class="club-name-field"><span>你的昵称</span><input name="name" maxlength="16" required placeholder="朋友们怎么称呼你？" value="${esc(p.name)}" autocomplete="nickname" ${p.activeRoom?'disabled':''}></label>
 <fieldset class="club-role-field"><legend>选择形象</legend><div class="club-avatars">${roles.map((name,i)=>`<label class="club-role-card" style="--role-tone:${tones[i]}"><input type="radio" name="role" value="${i}" ${p.role===i?'checked':''} ${p.activeRoom?'disabled':''}><span class="club-avatar" style="--pos:${i*100/3}%" aria-hidden="true"></span><span class="club-role-caption"><b>${name}</b><span class="club-role-check" aria-hidden="true">✓</span></span></label>`).join('')}</div></fieldset>
 <div class="club-form-actions"><span class="club-muted">${p.activeRoom?'离桌后可以修改形象与昵称。':first?'由管理员允许后进入游戏。':'形象会同步显示给同桌玩家。'}</span><button class="club-primary" type="submit" ${p.activeRoom?'disabled':''}>${first?'确认入座 →':'保存修改'}</button></div></form>
 ${p.activeRoom&&!p.settling?'<button class="club-secondary club-resume" data-resume>返回我的牌桌 →</button>':''}
 <div class="club-profile-footer"><details><summary>设备 ${esc(p.id.slice(0,8))}</summary><p>此浏览器会记住你的身份。换浏览器或清除数据后，需要重新允许。</p></details><button class="club-link" data-admin>${data.admin?'管理玩家 →':'管理员入口'}</button></div>`}
export function adminView(data){return `<p class="club-intro">管理朋友的入场权限与筹码。</p><div class="club-stats"><div><span>全部玩家</span><strong>${data.players.length}</strong></div><div><span>当前在线</span><strong>${data.players.filter(p=>p.online).length}</strong></div><div><span>等待允许</span><strong>${data.players.filter(p=>p.status==='pending').length}</strong></div></div>
 <div class="club-section-heading"><h3>玩家与设备</h3><span>自动更新在线状态</span></div><div class="club-player-list">${data.players.map(p=>`<article class="club-player-row"><div class="club-player-identity"><div class="club-mini-avatar" style="--pos:${p.role*100/3}%" aria-hidden="true"></div><div><strong>${esc(p.name||'尚未取名')}</strong><details class="club-device-detail"><summary>${device(p.agent)} · ${esc(p.id.slice(0,8))}</summary><p>${esc(p.agent)}<br>最近活跃：${date(p.seen)}</p></details></div></div><div class="club-player-status"><span class="club-status ${p.status}">${status(p)}</span><span class="club-muted"><i class="${p.online?'online':''}"></i>${p.online?'在线':'离线'}${p.activeRoom?' · 牌桌中':''}</span></div><div class="club-player-balance"><strong>${number(p.bank)}</strong><small>可用筹码${p.activeRoom?' · 桌上 '+number(p.tableBank):''}</small></div><div class="club-player-actions"><button class="club-secondary" data-permission="${p.id}" data-status="${p.status==='allowed'?'blocked':'allowed'}">${p.status==='allowed'?'停用设备':'允许进入'}</button><button class="club-link club-danger" data-delete="${p.id}" ${p.id===data.actorId?'disabled':''}>删除玩家</button><form data-grant="${p.id}"><input aria-label="发放给${esc(p.name||'该玩家')}的筹码数" type="number" inputmode="numeric" min="1" max="10000000" step="1" value="2000" required><button class="club-primary">发放</button></form></div></article>`).join('')||'<p class="club-empty">还没有玩家登记。</p>'}</div>
 ${roomManagement(data.rooms??[])}<p class="club-grant-note">发放的筹码立即存入余额；正在牌桌中的玩家会在下一局带入。</p><details class="club-history"><summary>最近管理记录 <span>${data.audit.length} 条</span></summary><div class="club-ledger">${data.audit.map(a=>`<p><time>${date(a.at)}</time><b>${esc(a.name||a.target.slice(0,8))}</b><span>${a.kind==='deletePlayer'?'删除玩家':a.kind==='closeRoom'?'关闭牌局':a.kind==='grant'?'发放 +'+number(a.amount):a.status==='allowed'?'允许访问':'停用设备'}</span></p>`).join('')||'<p class="club-muted">暂无记录</p>'}</div></details><div class="club-admin-footer"><button class="club-secondary" data-back>← 玩家中心</button><button class="club-link" data-logout>退出管理员</button></div>`}

function roomManagement(rooms){const titles={poker:'德州扑克',blackjack:'21点',craps:'花旗骰',roulette:'轮盘',guandan:'掼蛋'};return '<section class="club-rooms"><div class="club-section-heading"><h3>牌局管理</h3><span>20 分钟无真人操作自动关闭</span></div>'+ (rooms.map(r=>`<article class="club-room-row"><div><strong>${titles[r.mode]??esc(r.mode)}</strong><small>${esc(r.id.slice(0,8))} · ${r.humans} 位真人 / ${r.count} 个座位 · ${r.idleMinutes} 分钟无操作</small></div><button class="club-secondary" data-close-room="${r.id}">关闭牌局</button></article>`).join('')||'<p class="club-muted">当前没有牌局。</p>')+'</section>'}

function entryView(data){const p=data.player,first=!p.name,blocked=p.status==='blocked';return `<div class="club-admission"><p class="club-kicker">BRICK & BLUFF</p>${first?`<p class="club-intro">取一个昵称，申请加入牌局。</p><form data-profile><label class="club-name-field"><span>你的昵称</span><input name="name" maxlength="16" required placeholder="朋友们怎么称呼你？" autocomplete="nickname"></label><div class="club-form-actions"><span class="club-muted">首次加入获得 2,000 筹码</span><button class="club-primary" type="submit">申请进入 →</button></div></form>`:`<h3>${esc(p.name)}，${blocked?'暂时无法进入':'申请已提交'}</h3><p class="club-intro" role="status">${blocked?'此设备已被管理员停用，请联系管理员。':'正在等待管理员放行。通过后会自动进入游戏大厅，无需刷新。'}</p><span class="club-status ${p.status}">${blocked?'已停用':'等待管理员放行'}</span>`}<div class="club-profile-footer"><span class="club-muted">形象可在大厅中选择</span><button class="club-link" data-admin>${data.admin?'管理玩家 →':'管理员入口'}</button></div></div>`}
